      "family": "shipment_source_status",
      "request": "For outbound dispatch PGE-OUT-5002, determine which inbound material identities are established as contributing, what source location is established, and whether individual source allocation remains unresolved.",
      "parameters": {"dispatch": "PGE-OUT-5002"}
    },
    {
      "task_id": "EVAL-SRC-002",
      "family": "shipment_source_status",
      "request": "For outbound dispatch PGE-OUT-5003, determine the established source location, any established inbound material identity, and the missing or unresolved source linkage.",
      "parameters": {"dispatch": "PGE-OUT-5003"}
    },
    {
      "task_id": "EVAL-SRC-003",
      "family": "shipment_source_status",
      "request": "For outbound dispatch PGE-OUT-5004, determine which inbound material identities are established as contributing and whether the individual allocation is resolved.",
      "parameters": {"dispatch": "PGE-OUT-5004"}
    },
    {
      "task_id": "EVAL-PROV-001",
      "family": "processor_receipt_provenance",
      "request": "For processor receipt HFM-IN-602, summarize its upstream dispatch and inbound material identities, downstream processing output, and any unresolved allocation detail.",
      "parameters": {"processor_receipt": "HFM-IN-602"}
    },
    {
      "task_id": "EVAL-PROV-002",
      "family": "processor_receipt_provenance",
      "request": "For processor receipt HFM-IN-604, state the upstream dispatch and source status, whether an identified inbound load is established, and whether a processing output is recorded.",
      "parameters": {"processor_receipt": "HFM-IN-604"}
    },
    {
      "task_id": "EVAL-CUST-001",
      "family": "custody_owner_at",
      "request": "At 2025-09-04T13:10:00-05:00, determine the recorded owner and custodian of material WB-390.",
      "parameters": {"material": "WB-390", "timestamp": "2025-09-04T13:10:00-05:00"}
    },
