    {
      "task_id": "EVAL-INSP-001",
      "family": "inspection_downstream_scope",
      "request": "Determine what downstream shipment, processor receipt, and processed output are established as affected by inspection sample SMP-602B, and whether attribution to individual inbound material is resolved.",
